import * as THREE from 'three/webgpu';
import { texture, float, vec3, add, mul, pow, max, sub } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  // Tessellated plane geometry for displacement
  const geometry = new THREE.PlaneGeometry(1, 0.625, 64, 64);

  // Load textures
  const colorTexture = ctx.textureLoader.load(
    config.imageUrl || '/prism-mock/home/nodes/parallax-stack.png'
  );
  const depthTexture = ctx.textureLoader.load(
    config.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png'
  );

  colorTexture.colorSpace = THREE.SRGBColorSpace;

  // TSL shader nodes
  const colorSamp = texture(colorTexture);
  const depthSamp = texture(depthTexture);

  // Displacement from depth texture
  const displacementAmount = mul(depthSamp.r, float(0.08));

  // Rim light with accent color
  const accentColor = new THREE.Color('#ff2a38');
  const rimFactor = pow(max(sub(float(1), depthSamp.r), float(0)), float(2.0));
  const accentVec = vec3(
    float(accentColor.r),
    float(accentColor.g),
    float(accentColor.b)
  );
  const rimLight = mul(mul(accentVec, rimFactor), float(0.3));

  // Final color with rim lighting
  const finalColor = add(colorSamp, rimLight);

  // Machined-metal PBR material
  const material = new THREE.MeshPhysicalNodeMaterial({
    colorNode: finalColor,
    metalnessNode: float(0.4),
    roughnessNode: float(0.65),
    clearcoatNode: float(0.15),
    displacementNode: displacementAmount,
    side: THREE.DoubleSide,
    transparent: true,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.position[0], config.position[1], config.position[2]);
  mesh.scale.set(config.scale[0], config.scale[1], config.scale[2]);

  // Entrance: weighted-settle animation
  material.opacity = 0;
  mesh.scale.multiplyScalar(0.95);

  const entryTimeline = gsap.timeline();
  entryTimeline.to(material, { opacity: 1, duration: 0.9, ease: 'power4.out' }, 0);
  entryTimeline.to(
    mesh.scale,
    {
      x: config.scale[0],
      y: config.scale[1],
      z: config.scale[2],
      duration: 0.9,
      ease: 'power4.out',
      overwrite: false,
    },
    0
  );

  mesh.userData.timelines = [entryTimeline];
  mesh.userData.handlers = {};

  // Hover interaction: rise-in effect
  let hoverActive = false;
  const hoverTimeline = gsap.timeline({ paused: true });

  hoverTimeline.to(
    mesh.position,
    {
      y: config.position[1] + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    },
    0
  );

  mesh.userData.handlers.pointerenter = () => {
    if (!hoverActive) {
      hoverActive = true;
      hoverTimeline.play();
    }
  };

  mesh.userData.handlers.pointerleave = () => {
    if (hoverActive) {
      hoverActive = false;
      hoverTimeline.reverse();
    }
  };

  // Click handler: emit hub-home.select event
  mesh.userData.handlers.click = () => {
    if (config.emit && typeof config.emit === 'function') {
      config.emit('hub-home.select');
    }
  };

  // Apply cinematic primitives
  if (config.cinematicPrimitives && ctx.primitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      const fn = ctx.primitives[primitive.name];
      if (fn && typeof fn === 'function') {
        fn(mesh, primitive.params || {});
      }
    });
  }

  // Cleanup function
  mesh.userData.cleanup = () => {
    mesh.userData.timelines.forEach((tl) => tl.kill());
    hoverTimeline.kill();
    geometry.dispose();
    material.dispose();
    colorTexture.dispose();
    depthTexture.dispose();
  };

  return mesh;
}
